/**
 * 除錯插件
 *
 * 顯示播放器狀態、效能指標和事件日誌
 * 僅用於開發環境
 */

import type { MpvPlugin, PluginInstance } from '../../core/types/plugin';
import type { MpvVideoElement } from '../../renderer/ui/MpvVideoElement';
import styles from './styles.css?inline';

/**
 * 除錯面板位置
 */
export type DebugPanelPosition = 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right';

/**
 * 除錯插件配置
 */
export interface DebugPluginOptions {
    /** 是否顯示效能指標 */
    showPerformance?: boolean;
    /** 是否顯示狀態資訊 */
    showState?: boolean;
    /** 是否記錄事件 */
    logEvents?: boolean;
    /** 面板位置 */
    position?: DebugPanelPosition;
    /** 最大事件記錄數 */
    maxEventLogs?: number;
    /** 自訂要監控的事件 */
    watchEvents?: string[];
}

/**
 * 效能指標
 */
interface PerformanceMetrics {
    actualFps: number;
    nativeFps: number;
    targetFps: number;
    effectiveFps: number;
    degradationLevel: number;
    lastUpdate: number;
}

/**
 * 除錯插件定義
 */
export const DebugPlugin: MpvPlugin<DebugPluginOptions> = {
    name: 'debug',
    version: '1.0.0',
    styles,

    install(player, options = {}) {
        return new DebugManager(player, {
            showPerformance: options.showPerformance ?? true,
            showState: options.showState ?? true,
            logEvents: options.logEvents ?? true,
            position: options.position ?? 'top-left',
            maxEventLogs: options.maxEventLogs ?? 50,
            watchEvents: options.watchEvents ?? [
                'loadstart', 'loadedmetadata', 'loadeddata',
                'canplay', 'canplaythrough',
                'play', 'playing', 'pause', 'ended',
                'seeking', 'seeked',
                'waiting', 'stalled', 'error',
            ],
        });
    },
};

/**
 * 除錯管理器
 */
export class DebugManager implements PluginInstance {
    readonly name = 'debug';

    private player: MpvVideoElement;
    private options: Required<DebugPluginOptions>;

    // DOM 元素
    private panelEl: HTMLElement | null = null;
    private toggleBtn: HTMLElement | null = null;
    private performanceEl: HTMLElement | null = null;
    private stateEl: HTMLElement | null = null;
    private eventsEl: HTMLElement | null = null;
    /** 緩存內容元素，避免每次 updateUI 時重複 querySelector */
    private performanceContent: HTMLElement | null = null;
    private stateContent: HTMLElement | null = null;
    private eventsContent: HTMLElement | null = null;

    /** 緩存值元素引用，避免 innerHTML 重建 DOM 造成內存洩漏 */
    private perfValueEls: {
        actualFps: HTMLElement | null;
        nativeFps: HTMLElement | null;
        targetFps: HTMLElement | null;
        degradation: HTMLElement | null;
    } = { actualFps: null, nativeFps: null, targetFps: null, degradation: null };

    private stateValueEls: {
        time: HTMLElement | null;
        paused: HTMLElement | null;
        volume: HTMLElement | null;
        speed: HTMLElement | null;
        loop: HTMLElement | null;
        ready: HTMLElement | null;
    } = { time: null, paused: null, volume: null, speed: null, loop: null, ready: null };

    /** 緩存上一次的事件日誌長度，只在變化時更新 */
    private lastEventLogsLength: number = 0;

    // 狀態
    private _enabled: boolean = true;
    private _visible: boolean = false;
    private eventLogs: Array<{ time: number; event: string; data?: unknown }> = [];
    private metrics: PerformanceMetrics = {
        actualFps: 0,
        nativeFps: 0,
        targetFps: 0,
        effectiveFps: 0,
        degradationLevel: 0,
        lastUpdate: 0,
    };

    // 定時器
    private updateInterval: ReturnType<typeof setInterval> | null = null;

    // 事件處理器
    private eventHandlers: Map<string, (e: Event) => void> = new Map();

    constructor(player: MpvVideoElement, options: Required<DebugPluginOptions>) {
        this.player = player;
        this.options = options;

        this.initialize();
    }

    private initialize(): void {
        this.createUI();
        this.bindEvents();
        this.startMetricsCollection();
    }

    private createUI(): void {
        const shadowRoot = this.player.shadowRoot;
        if (!shadowRoot) return;

        // 創建控制列切換按鈕
        this.createToggleButton(shadowRoot);

        // 創建面板容器
        this.panelEl = document.createElement('div');
        this.panelEl.className = 'mpv-debug-panel hidden';

        // 效能區塊 - 創建固定結構，緩存值元素引用
        if (this.options.showPerformance) {
            this.performanceEl = document.createElement('div');
            this.performanceEl.className = 'mpv-debug-section mpv-debug-performance';
            this.performanceEl.innerHTML = `
                <div class="mpv-debug-title">Performance</div>
                <div class="mpv-debug-content">
                    <div class="mpv-debug-row"><span class="mpv-debug-label">Actual FPS:</span><span class="mpv-debug-value" data-field="actualFps">0</span></div>
                    <div class="mpv-debug-row"><span class="mpv-debug-label">Native FPS:</span><span class="mpv-debug-value" data-field="nativeFps">0</span></div>
                    <div class="mpv-debug-row"><span class="mpv-debug-label">Target FPS:</span><span class="mpv-debug-value" data-field="targetFps">0</span></div>
                    <div class="mpv-debug-row"><span class="mpv-debug-label">Degradation:</span><span class="mpv-debug-value" data-field="degradation">0</span></div>
                </div>`;
            this.performanceContent = this.performanceEl.querySelector('.mpv-debug-content');
            this.perfValueEls = {
                actualFps: this.performanceEl.querySelector('[data-field="actualFps"]'),
                nativeFps: this.performanceEl.querySelector('[data-field="nativeFps"]'),
                targetFps: this.performanceEl.querySelector('[data-field="targetFps"]'),
                degradation: this.performanceEl.querySelector('[data-field="degradation"]'),
            };
            this.panelEl.appendChild(this.performanceEl);
        }

        // 狀態區塊 - 創建固定結構，緩存值元素引用
        if (this.options.showState) {
            this.stateEl = document.createElement('div');
            this.stateEl.className = 'mpv-debug-section mpv-debug-state';
            this.stateEl.innerHTML = `
                <div class="mpv-debug-title">State</div>
                <div class="mpv-debug-content">
                    <div class="mpv-debug-row"><span class="mpv-debug-label">Time:</span><span class="mpv-debug-value" data-field="time">--:-- / --:--</span></div>
                    <div class="mpv-debug-row"><span class="mpv-debug-label">Paused:</span><span class="mpv-debug-value" data-field="paused">true</span></div>
                    <div class="mpv-debug-row"><span class="mpv-debug-label">Volume:</span><span class="mpv-debug-value" data-field="volume">100%</span></div>
                    <div class="mpv-debug-row"><span class="mpv-debug-label">Speed:</span><span class="mpv-debug-value" data-field="speed">1x</span></div>
                    <div class="mpv-debug-row"><span class="mpv-debug-label">Loop:</span><span class="mpv-debug-value" data-field="loop">false</span></div>
                    <div class="mpv-debug-row"><span class="mpv-debug-label">Ready:</span><span class="mpv-debug-value" data-field="ready">0</span></div>
                </div>`;
            this.stateContent = this.stateEl.querySelector('.mpv-debug-content');
            this.stateValueEls = {
                time: this.stateEl.querySelector('[data-field="time"]'),
                paused: this.stateEl.querySelector('[data-field="paused"]'),
                volume: this.stateEl.querySelector('[data-field="volume"]'),
                speed: this.stateEl.querySelector('[data-field="speed"]'),
                loop: this.stateEl.querySelector('[data-field="loop"]'),
                ready: this.stateEl.querySelector('[data-field="ready"]'),
            };
            this.panelEl.appendChild(this.stateEl);
        }

        // 事件日誌區塊
        if (this.options.logEvents) {
            this.eventsEl = document.createElement('div');
            this.eventsEl.className = 'mpv-debug-section mpv-debug-events';
            this.eventsEl.innerHTML = '<div class="mpv-debug-title">Events</div><div class="mpv-debug-content"></div>';
            this.eventsContent = this.eventsEl.querySelector('.mpv-debug-content');
            this.panelEl.appendChild(this.eventsEl);
        }

        // 注入樣式
        this.injectStyles(shadowRoot);

        shadowRoot.appendChild(this.panelEl);
    }

    private createToggleButton(shadowRoot: ShadowRoot): void {
        const container = shadowRoot.querySelector('.vp-controls-right');
        if (!container) return;

        this.toggleBtn = document.createElement('button');
        this.toggleBtn.className = 'vp-btn vp-debug-btn';
        this.toggleBtn.title = '除錯面板 (D)';
        this.toggleBtn.dataset.order = '95';
        this.toggleBtn.textContent = '除錯';

        this.toggleBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.toggle();
        });

        // 按順序插入
        this.insertByOrder(container, this.toggleBtn);
    }

    private insertByOrder(container: Element, element: HTMLElement): void {
        const order = parseInt(element.dataset.order || '999', 10);
        const children = Array.from(container.children) as HTMLElement[];

        const insertBefore = children.find(child => {
            const childOrder = parseInt(child.dataset.order || '999', 10);
            return childOrder > order;
        });

        if (insertBefore) {
            container.insertBefore(element, insertBefore);
        } else {
            container.appendChild(element);
        }
    }

    private injectStyles(shadowRoot: ShadowRoot): void {
        if (shadowRoot.querySelector('#mpv-debug-styles')) return;

        const positionStyles: Record<DebugPanelPosition, string> = {
            'top-left': 'top: 10px; left: 10px;',
            'top-right': 'top: 10px; right: 10px;',
            'bottom-left': 'bottom: 60px; left: 10px;',
            'bottom-right': 'bottom: 60px; right: 10px;',
        };

        const style = document.createElement('style');
        style.id = 'mpv-debug-styles';
        style.textContent = `
            .mpv-debug-panel {
                position: absolute;
                ${positionStyles[this.options.position]}
                background: rgba(0, 0, 0, 0.85);
                color: #0f0;
                font-family: 'Monaco', 'Menlo', 'Consolas', monospace;
                font-size: 11px;
                padding: 8px;
                border-radius: 4px;
                z-index: 9999;
                max-width: 300px;
                max-height: 400px;
                overflow: auto;
                pointer-events: auto;
            }
            .mpv-debug-panel.hidden {
                display: none;
            }
            .mpv-debug-section {
                margin-bottom: 8px;
            }
            .mpv-debug-section:last-child {
                margin-bottom: 0;
            }
            .mpv-debug-title {
                color: #ff0;
                font-weight: bold;
                margin-bottom: 4px;
                border-bottom: 1px solid #333;
                padding-bottom: 2px;
            }
            .mpv-debug-content {
                line-height: 1.4;
            }
            .mpv-debug-row {
                display: flex;
                justify-content: space-between;
            }
            .mpv-debug-label {
                color: #aaa;
            }
            .mpv-debug-value {
                color: #0f0;
            }
            .mpv-debug-events .mpv-debug-content {
                max-height: 150px;
                overflow-y: auto;
            }
            .mpv-debug-event {
                padding: 2px 0;
                border-bottom: 1px solid #222;
            }
            .mpv-debug-event-time {
                color: #888;
                margin-right: 8px;
            }
            .mpv-debug-event-name {
                color: #0af;
            }

            .mpv-debug-panel::-webkit-scrollbar,
            .mpv-debug-events .mpv-debug-content::-webkit-scrollbar {
                width: 6px;
                height: 6px;
            }
            .mpv-debug-panel::-webkit-scrollbar-track,
            .mpv-debug-events .mpv-debug-content::-webkit-scrollbar-track {
                border-radius: 3px;
            }
            .mpv-debug-panel::-webkit-scrollbar-thumb,
            .mpv-debug-events .mpv-debug-content::-webkit-scrollbar-thumb {
                border-radius: 3px;
            }

            /* Debug toggle button */
            .vp-debug-btn {
                width: auto;
                display: flex;
                align-items: center;
                justify-content: center;
                padding: 0 4px;
                color: var(--vp-text-color, #2c2f32);
                opacity: 0.5;
            }
            .vp-debug-btn.active {
                opacity: 1;
            }
        `;
        shadowRoot.appendChild(style);
    }

    private bindEvents(): void {
        for (const eventName of this.options.watchEvents) {
            const handler = (e: Event) => this.logEvent(eventName, e);
            this.eventHandlers.set(eventName, handler);
            this.player.addEventListener(eventName, handler);
        }
    }

    private startMetricsCollection(): void {
        this.updateInterval = setInterval(() => {
            if (!this._enabled || !this._visible) return;
            this.updateMetrics();
            this.updateUI();
        }, 500);
    }

    private updateMetrics(): void {
        const playerAny = this.player as unknown as {
            getFpsStats?(): {
                actualFps: number;
                nativeFps: number;
                targetFps: number;
                effectiveFps: number;
                degradationLevel: number;
            };
        };

        if (typeof playerAny.getFpsStats === 'function') {
            const stats = playerAny.getFpsStats();
            this.metrics = {
                actualFps: stats.actualFps,
                nativeFps: stats.nativeFps,
                targetFps: stats.targetFps,
                effectiveFps: stats.effectiveFps,
                degradationLevel: stats.degradationLevel,
                lastUpdate: performance.now(),
            };
        }
    }

    private updateUI(): void {
        // 更新效能區塊 - 使用 textContent 更新值，避免 DOM 重建
        if (this.perfValueEls.actualFps) {
            this.perfValueEls.actualFps.textContent = this.metrics.actualFps.toFixed(1);
        }
        if (this.perfValueEls.nativeFps) {
            this.perfValueEls.nativeFps.textContent = this.metrics.nativeFps.toFixed(1);
        }
        if (this.perfValueEls.targetFps) {
            this.perfValueEls.targetFps.textContent = this.metrics.targetFps.toFixed(1);
        }
        if (this.perfValueEls.degradation) {
            this.perfValueEls.degradation.textContent = String(this.metrics.degradationLevel);
        }

        // 更新狀態區塊 - 使用 textContent 更新值，避免 DOM 重建
        if (this.stateValueEls.time) {
            this.stateValueEls.time.textContent = `${this.formatTime(this.player.currentTime)} / ${this.formatTime(this.player.duration)}`;
        }
        if (this.stateValueEls.paused) {
            this.stateValueEls.paused.textContent = String(this.player.paused);
        }
        if (this.stateValueEls.volume) {
            this.stateValueEls.volume.textContent = `${(this.player.volume * 100).toFixed(0)}%`;
        }
        if (this.stateValueEls.speed) {
            this.stateValueEls.speed.textContent = `${this.player.playbackRate}x`;
        }
        if (this.stateValueEls.loop) {
            this.stateValueEls.loop.textContent = String(this.player.loop);
        }
        if (this.stateValueEls.ready) {
            this.stateValueEls.ready.textContent = String(this.player.readyState);
        }

        // 更新事件日誌 - 只在日誌數量變化時重建 DOM
        if (this.eventsContent && this.eventLogs.length !== this.lastEventLogsLength) {
            this.lastEventLogsLength = this.eventLogs.length;
            const recentEvents = this.eventLogs.slice(-10).reverse();
            this.eventsContent.innerHTML = recentEvents.map(log => `
                <div class="mpv-debug-event">
                    <span class="mpv-debug-event-time">${this.formatEventTime(log.time)}</span>
                    <span class="mpv-debug-event-name">${log.event}</span>
                </div>
            `).join('');
        }
    }

    private logEvent(eventName: string, _e: Event): void {
        if (!this._enabled) return;

        this.eventLogs.push({
            time: Date.now(),
            event: eventName,
        });

        // 限制日誌數量
        if (this.eventLogs.length > this.options.maxEventLogs) {
            this.eventLogs.shift();
        }
    }

    private formatTime(seconds: number): string {
        if (!isFinite(seconds)) return '--:--';
        const mins = Math.floor(seconds / 60);
        const secs = Math.floor(seconds % 60);
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    }

    private formatEventTime(timestamp: number): string {
        const date = new Date(timestamp);
        return `${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}:${date.getSeconds().toString().padStart(2, '0')}`;
    }

    // ===== 公開 API =====

    /** 顯示除錯面板 */
    show(): void {
        this._visible = true;
        this.panelEl?.classList.remove('hidden');
        this.toggleBtn?.classList.add('active');
    }

    /** 隱藏除錯面板 */
    hide(): void {
        this._visible = false;
        this.panelEl?.classList.add('hidden');
        this.toggleBtn?.classList.remove('active');
    }

    /** 切換除錯面板顯示 */
    toggle(): void {
        if (this._visible) {
            this.hide();
        } else {
            this.show();
        }
    }

    /** 是否可見 */
    get visible(): boolean {
        return this._visible;
    }

    /** 獲取效能指標 */
    getMetrics(): PerformanceMetrics {
        return { ...this.metrics };
    }

    /** 獲取事件日誌 */
    getEventLogs(): Array<{ time: number; event: string }> {
        return [...this.eventLogs];
    }

    /** 清空事件日誌 */
    clearEventLogs(): void {
        this.eventLogs = [];
    }

    enable(): void {
        this._enabled = true;
        this.show();
    }

    disable(): void {
        this._enabled = false;
        this.hide();
    }

    get enabled(): boolean {
        return this._enabled;
    }

    destroy(): void {
        // 清理定時器
        if (this.updateInterval) {
            clearInterval(this.updateInterval);
            this.updateInterval = null;
        }

        // 移除事件監聽
        for (const [eventName, handler] of this.eventHandlers) {
            this.player.removeEventListener(eventName, handler);
        }
        this.eventHandlers.clear();

        // 清理緩存的元素引用
        this.perfValueEls = { actualFps: null, nativeFps: null, targetFps: null, degradation: null };
        this.stateValueEls = { time: null, paused: null, volume: null, speed: null, loop: null, ready: null };
        this.performanceContent = null;
        this.stateContent = null;
        this.eventsContent = null;

        // 清理事件日誌
        this.eventLogs = [];
        this.lastEventLogsLength = 0;

        // 移除 DOM
        this.toggleBtn?.remove();
        this.panelEl?.remove();
        this.toggleBtn = null;
        this.panelEl = null;
    }
}

